mapper.select:
SELECT COUNT(*) FROM (
 SELECT SUBJECT_ID FROM SMT_AUTH_TRANSPORT_PHASE WHERE INSTANCE_ID=#{p.instanceId} AND ACCESS_TYPE='ISC' AND PERSON_ID=#{person} AND (SUBJECT_TYPE!=#{p.subjectType} OR SUBJECT_ID!=#{p.subjectId})
 UNION ALL SELECT A.SUBJECT_ID FROM SMT_AUTH_IDENTITY_ALIAS A JOIN SMT_AUTH_SCHEDULER_ROUTE R ON R.PARK_ID=A.PARK_ID AND R.ACCESS_TYPE='ISC' AND R.INSTANCE_ID=#{p.instanceId}
 WHERE A.ACCESS_TYPE='ISC' AND A.ALIAS_KIND='PERSON_ID' AND A.ALIAS_VALUE=#{person} AND (A.SUBJECT_TYPE!=#{p.subjectType} OR A.SUBJECT_ID!=#{p.subjectId})
 UNION ALL SELECT D.CARD_NO FROM SMT_ISC_DOWN_RECORD D JOIN SMT_AUTH_SCHEDULER_ROUTE R ON R.PARK_ID=D.PARK_ID AND R.ACCESS_TYPE='ISC' AND R.INSTANCE_ID=#{p.instanceId}
 WHERE D.PERSON_ID=#{person} AND (D.DEVICE_TYPE!=1 OR D.CARD_NO!=#{p.subjectId})
 UNION ALL SELECT K.CARD_NO FROM SMT_ISC_DEVICE_TASK K JOIN SMT_DEVICE D ON D.ID=K.DEVICE_CODE JOIN SMT_AUTH_SCHEDULER_ROUTE R ON R.PARK_ID=D.PARK_ID AND R.ACCESS_TYPE='ISC' AND R.INSTANCE_ID=#{p.instanceId}
 WHERE K.PERSON_ID=#{person} AND (K.DEVICE_TYPE!=1 OR K.CARD_NO!=#{p.subjectId})
 ) WHERE ROWNUM=1
